const page = await browser.goto('https://github.com/pfirsich/OpenClaw');
const title = await browser.js('document.title');
const url = page.url;
return {title, url};

const page = await browser.goto('https://github.com/search?q=OpenClaw&type=repositories');
await browser.waitFor("document.querySelectorAll('a[href*=\"/\"]').length > 5");
const links = await browser.js(`
  Array.from(document.querySelectorAll('a')).map(a => ({text: a.textContent.trim(), href: a.href}))
    .filter(x => x.href.includes('github.com/') && x.text.length > 0 && !x.href.includes('/search'))
    .slice(0, 60)
`);
return links;

const results = [];
const candidates = [
  'https://github.com/pjasicek/OpenClaw',
  'https://github.com/OpenClaw/OpenClaw',
];
for (const url of candidates) {
  try {
    const page = await browser.goto(url);
    const title = await browser.js('document.title');
    results.push({url, finalUrl: page.url, title});
  } catch (e) {
    results.push({url, error: String(e)});
  }
}
return results;

const results = [];
const candidates = [
  'https://github.com/pjasicek/OpenClaw',
  'https://github.com/openclaw/openclaw',
];
for (const url of candidates) {
  const page = await browser.goto(url);
  const info = await browser.js(`(() => {
    const stars = document.querySelector('a[href$="/stargazers"]')?.textContent.trim();
    const forks = document.querySelector('a[href$="/forks"]')?.textContent.trim();
    const desc = document.querySelector('p.f4')?.textContent.trim() || document.querySelector('[itemprop="description"]')?.textContent.trim();
    return {stars, forks, desc};
  })()`);
  results.push({url, ...info});
}
return results;

